import Link from 'next/link';import { api } from '@/lib/api';import { TicketFilters } from '@/components/TicketFilters';
export default async function Page({searchParams}:{searchParams:Promise<Record<string,string|string[]|undefined>>}){const p=await searchParams;const qs=new URLSearchParams();Object.entries(p).forEach(([k,v])=>{if(typeof v==='string')qs.set(k,v)});if(!qs.has('page'))qs.set('page','1');if(!qs.has('limit'))qs.set('limit','10');const [data,agents]=await Promise.all([api.tickets(qs.toString()),api.agents()]);function page(n:number){const x=new URLSearchParams(qs);x.set('page',String(n));return `/tickets?${x}`};return <><div className="mb-5 flex justify-between"><div><h1 className="text-3xl font-black">Tickets</h1><p className="text-slate-500">{data.total} total tickets</p></div><Link href="/tickets/new" className="btn btn-primary">+ Create</Link></div><TicketFilters agents={agents}/><div className="card overflow-hidden">{data.data.length===0?<div className="p-10 text-center"><h2 className="font-bold">No tickets found</h2><p className="text-slate-500">Try changing your search or filters.</p></div>:<div className="overflow-x-auto"><table className="w-full min-w-[950px] text-left text-sm"><thead className="bg-slate-50"><tr>{['ID','Customer','Subject','Priority','Status','Agent','Created'].map(x=><th className="p-3" key={x}>{x}</th>)}</tr></thead><tbody>{data.data.map(t=><tr className="border-t" key={t.id}><td className="p-3"><Link href={`/tickets/${t.id}`} className="font-bold underline">#{t.id}</Link></td><td className="p-3"><b>{t.customer_name}</b><br/><span className="text-xs text-slate-500">{t.customer_email}</span></td><td className="p-3">{t.subject}</td><td className="p-3"><span className="badge">{t.priority}</span></td><td className="p-3">{t.status}</td><td className="p-3">{t.agent_name??'Unassigned'}</td><td className="p-3">{new Date(t.created_at).toLocaleDateString()}</td></tr>)}</tbody></table></div>}<div className="flex items-center justify-between border-t p-4 text-sm"><span>Page {data.page} of {Math.max(data.totalPages,1)}</span><div className="flex gap-2">{data.page>1&&<Link className="btn btn-secondary" href={page(data.page-1)}>Previous</Link>}{data.page<data.totalPages&&<Link className="btn btn-secondary" href={page(data.page+1)}>Next</Link>}</div></div></div></>}
